style.css:
@-moz-document domain("animego.org") {
/* 1. Устанавливаем фон для всего сайта */
    body {
        background: url('https://avatars.mds.yandex.net/i?id=556e35996dccb8bbd9cd2f49b444a22b57177423-4697805-images-thumbs&n=13') fixed center top !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
    }

    /* 2. Затемняем область за хедером (шапкой сайта) для читаемости */
    .navbar-wrapper,
    .navbar {
        background-color: rgba(18, 20, 26, 0.92) !important;
        backdrop-filter: blur(8px) !important;
        border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
    }

    /* 3. Основной контейнер с аниме-контентом - делаем его полупрозрачным */
    .container,
    .container-fluid {
        background-color: rgba(18, 20, 26, 0.88) !important;
        border-radius: 12px !important;
        padding: 20px !important;
        margin-top: 20px !important;
        margin-bottom: 20px !important;
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4) !important;
        backdrop-filter: blur(12px) !important;
        border: 1px solid rgba(255, 255, 255, 0.08) !important;
    }

    /* 4. Карточки аниме и постов - делаем их немного темнее */
    .anime-card,
    .media,
    .video-item,
    .card,
    .list-item,
    .comment-body {
        background-color: rgba(26, 29, 38, 0.85) !important;
        border-color: rgba(255, 255, 255, 0.05) !important;
        border-radius: 8px !important;
    }

    /* 5. Улучшаем читаемость текста */
    body,
    .card-title,
    .media-body p,
    .comment-text,
    .anime-title {
        color: #e0e0e0 !important;
        text-shadow: 0 1px 2px rgba(0, 0, 0, 0.5) !important;
    }

    /* 6. Особые правки для ссылок */
    a:not(.btn):not(.badge) {
        color: #6ab0ff !important;
    }
    a:hover:not(.btn):not(.badge) {
        color: #8bc7ff !important;
        text-decoration: none !important;
    }

    /* 7. Футер (подвал сайта) */
    footer {
        background-color: rgba(10, 12, 16, 0.95) !important;
        border-top: 1px solid rgba(255, 255, 255, 0.05) !important;
    }

    /* 8. Убираем возможные белые фоны у элементов */
    .bg-white,
    .bg-light {
        background-color: transparent !important;
    }
}
